1	/**
2	 * SFCC-84 build plan step B2 — asserts only this container's own contract
3	 * (`.claude/rules/testing.md`'s no-duplicate-coverage rule): given `useRecentlyViewedHistory`'s
4	 * return value, does it render `ZimmRecentlyViewedGrid` (with the right computed `title`/
5	 * `itemCountLabel`/`cards`) or this page's own empty state, correctly branched on
6	 * `isRegistered`; and does the item-count label actually pluralize via real ICU `plural`
7	 * resolution. `useRecentlyViewedHistory`, `useRecentlyViewedProductFetch`,
8	 * `selectRecentlyViewedFullHistoryCard` and `ZimmRecentlyViewedGrid` are all mocked at the
9	 * smallest surface — their own internals already have their own coverage elsewhere
10	 * (`useRecentlyViewedHistory.test.ts`, `recentlyViewedProductFetch.test.ts`,
11	 * `recentlyViewedFullHistoryCard.test.ts`, `zimmRecentlyViewedGrid/index.test.tsx`). Same
12	 * smallest-surface-mocking convention `recommended-products/index.test.tsx` already establishes
13	 * for an almost identical container shape (mocks the child organism it renders, the history hook,
14	 * and the product-fetch utility).
15	 *
16	 * `useMultiSite` is mocked the same way `footer/index.test.tsx` already does for the same reason:
17	 * the empty state's CTAs use the base SFCC `Link` (`@salesforce/retail-react-app/app/components/
18	 * link`), which calls `useMultiSite().buildUrl` internally to site-prefix `href`. A real
19	 * `MemoryRouter` is still required underneath it (that `Link` renders a real `react-router-dom`
20	 * `Link`), matching `footer/index.test.tsx`'s own `renderContainer` wrapper.
21	 *
22	 * The item-count pluralization tests deliberately do NOT mock `react-intl` — an `IntlProvider`
23	 * with an empty `messages` map (matching `recommended-products/index.test.tsx`'s own
24	 * `<IntlProvider locale="en-AU" messages={{}}>`) falls back to each message's own
25	 * `defaultMessage`, so `formatMessage`'s real ICU `plural` resolution runs for real. Mocking
26	 * `formatMessage` itself would defeat the point of this specific test.
27	 */
28	import React from 'react';
29	import { describe, test, expect, vi, afterEach } from 'vitest';
30	import { render, screen, act } from '@testing-library/react';
31	import { IntlProvider } from 'react-intl';
32	import { MemoryRouter } from 'react-router-dom';
33	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
34	import { useCustomerType, useShopperBasketsMutationHelper } from '@salesforce/commerce-sdk-react';
35	import { useRecentlyViewedHistory } from '../../hooks/useRecentlyViewedHistory';
36	import { useRecentlyViewedProductFetch } from '../../utils/recentlyViewedProductFetch';
37	import {
38	  selectRecentlyViewedFullHistoryCard,
39	  resolveOrderableVariant,
40	} from '../../utils/recentlyViewedFullHistoryCard';
41	import type { RecentlyViewedFullHistoryProduct } from '../../utils/recentlyViewedFullHistoryCard';
42	import { ZimmRecentlyViewedGrid } from '../../components/ui-kits/organisms/zimmRecentlyViewedGrid';
43	import type { ZimmProductCardProps } from '../../components/ui-kits/organisms/zimmProductCard';
44	import RecentlyViewed from '.';
45	
46	// Every card this file's own buildCard() builds is `variation: 'plp'` -- narrows the rendered
47	// `ZimmProductCardProps` union so onAddToBag/selectedSizeChipValue/onSizeChipSelect (all `plp`-only
48	// fields) are accessible, matching product-list/index.tsx's own `ProductListCardProps`
49	// `Extract<ZimmProductCardProps, { variation: 'plp' }>` pattern.
50	const asPlpCard = (card: ZimmProductCardProps) => card as Extract<ZimmProductCardProps, { variation: 'plp' }>;
51	
52	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
53	  default: vi.fn(),
54	}));
55	
56	vi.mock('@salesforce/commerce-sdk-react', () => ({
57	  useCustomerType: vi.fn(),
58	  useShopperBasketsMutationHelper: vi.fn(),
59	}));
60	
61	// Real use-toast.js ships JSX in a .js-extension file that Vitest's default transform can't parse
62	// when pulled in transitively — same known gap use-toast.js has everywhere else it's imported in
63	// this codebase's own tests (see recommended-products/index.test.tsx's identical mock).
64	vi.mock('@salesforce/retail-react-app/app/hooks/use-toast', () => ({
65	  useToast: () => vi.fn(),
66	}));
67	
68	vi.mock('../../hooks/useRecentlyViewedHistory', () => ({
69	  useRecentlyViewedHistory: vi.fn(),
70	}));
71	
72	vi.mock('../../utils/recentlyViewedProductFetch', () => ({
73	  useRecentlyViewedProductFetch: vi.fn(),
74	}));
75	
76	vi.mock('../../utils/recentlyViewedFullHistoryCard', () => ({
77	  selectRecentlyViewedFullHistoryCard: vi.fn(),
78	  resolveOrderableVariant: vi.fn(),
79	}));
80	
81	// Relative path, matching index.tsx's own import — overrideStyling.md's "Importing an
82	// already-overridden component" doctrine (irrelevant here in the base-path sense, since this
83	// organism has no base-SFCC equivalent at all, but the relative specifier must still match
84	// exactly for the mock to intercept the real import).
85	vi.mock('../../components/ui-kits/organisms/zimmRecentlyViewedGrid', () => ({
86	  ZimmRecentlyViewedGrid: vi.fn(() => <div data-testid="zimm-recently-viewed-grid-stub" />),
87	}));
88	
89	const mockUseMultiSite = vi.mocked(useMultiSite);
90	const mockUseCustomerType = vi.mocked(useCustomerType);
91	const mockUseShopperBasketsMutationHelper = vi.mocked(useShopperBasketsMutationHelper);
92	const mockUseRecentlyViewedHistory = vi.mocked(useRecentlyViewedHistory);
93	const mockUseRecentlyViewedProductFetch = vi.mocked(useRecentlyViewedProductFetch);
94	const mockSelectRecentlyViewedFullHistoryCard = vi.mocked(selectRecentlyViewedFullHistoryCard);
95	const mockResolveOrderableVariant = vi.mocked(resolveOrderableVariant);
96	const mockZimmRecentlyViewedGrid = vi.mocked(ZimmRecentlyViewedGrid);
97	
98	// Two products, deliberately different `id`s, so a mapping/filtering bug (wrong product picked,
99	// or the null-filter dropping the wrong entry) fails loudly rather than coincidentally matching —
100	// same "G1" doctrine recentlyViewedCard.test.ts/recentlyViewedFullHistoryCard.test.ts document.
101	const mockProducts: RecentlyViewedFullHistoryProduct[] = [
102	  { id: 'rv-1', name: 'Product One' } as RecentlyViewedFullHistoryProduct,
103	  { id: 'rv-2', name: 'Product Two' } as RecentlyViewedFullHistoryProduct,
104	];
105	
